package top.dcpstudios.calendarwidget;

import android.app.*;import android.content.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

final class TimetableScreen {
    final MainActivity a;int selectedWeek=-1;JSONObject data;
    TimetableScreen(MainActivity activity){a=activity;}
    void show(){try{
        data=TimetableStore.load(a);JSONObject term=data.getJSONObject("term");int first=term.getInt("start_week"),last=term.getInt("end_week");long monday=TimetableData.monday(term.getString("week1_monday"));
        int actual=TimetableData.week(monday,System.currentTimeMillis());if(selectedWeek<first||selectedWeek>last)selectedWeek=Math.max(first,Math.min(last,actual));
        a.base("timetable");a.screenTitle("课表",term.optString("name")+" · "+(actual<first?"尚未开学":actual>last?"学期已结束":"当前第 "+actual+" 周"));
        LinearLayout nav=new LinearLayout(a);nav.addView(a.button("‹",()->{selectedWeek=Math.max(first,selectedWeek-1);show();}),new LinearLayout.LayoutParams(0,a.d(44),1));nav.addView(a.button("第 "+selectedWeek+" 周",()->pickWeek(first,last)),new LinearLayout.LayoutParams(0,a.d(44),3));nav.addView(a.button("›",()->{selectedWeek=Math.min(last,selectedWeek+1);show();}),new LinearLayout.LayoutParams(0,a.d(44),1));a.root.addView(nav);a.space(a.root,10);
        HorizontalScrollView horizontal=new HorizontalScrollView(a);FrameLayout grid=new FrameLayout(a);
        int label=a.d(34),cell=(a.getResources().getDisplayMetrics().widthPixels-a.d(32)-label)/5,row=a.d(60),top=a.d(34);int width=label+7*cell,height=top+11*row;
        grid.setLayoutParams(new android.widget.FrameLayout.LayoutParams(width,height));grid.setBackground(a.bg(a.surface,18));
        java.text.SimpleDateFormat dayFormat=new java.text.SimpleDateFormat("M/d",Locale.CHINA);dayFormat.setTimeZone(TimetableData.ZONE);
        String[] days={"一","二","三","四","五","六","日"};
        for(int day=1;day<=7;day++){long date=monday+((selectedWeek-1)*7L+day-1)*86400000;TextView h=a.text("周"+days[day-1]+"\n"+dayFormat.format(new Date(date)),10,a.muted);h.setGravity(Gravity.CENTER);place(grid,h,label+(day-1)*cell,0,cell,top);}
        JSONArray periods=data.getJSONArray("periods");for(int p=1;p<=11;p++){JSONObject timing=periods.getJSONObject(p-1);TextView number=a.text(p+"\n"+timing.getString("start"),9,a.muted);number.setGravity(Gravity.CENTER);place(grid,number,0,top+(p-1)*row,label,row);View divider=new View(a);divider.setBackgroundColor(a.line);place(grid,divider,label,top+(p-1)*row,width-label,1);}
        JSONArray courses=data.getJSONArray("courses");int visible=0;
        for(int i=0;i<courses.length();i++){JSONObject course=courses.getJSONObject(i);if(!TimetableStore.numbers(course.getJSONArray("weeks"),first,last).contains(selectedWeek))continue;visible++;
            SortedSet<Integer> numbers=TimetableStore.numbers(course.getJSONArray("periods"),1,11);List<Integer> parts=new ArrayList<>(numbers);int segment=0;
            while(segment<parts.size()){int start=parts.get(segment),end=start;while(segment+1<parts.size()&&parts.get(segment+1)==end+1){segment++;end++;}segment++;
                int day=course.getInt("day"),overlapIndex=0,overlapCount=1;
                for(int j=0;j<courses.length();j++){if(j==i)continue;JSONObject other=courses.getJSONObject(j);if(other.getInt("day")!=day||!TimetableStore.numbers(other.getJSONArray("weeks"),first,last).contains(selectedWeek))continue;
                    Set<Integer> otherParts=TimetableStore.numbers(other.getJSONArray("periods"),1,11);boolean intersects=false;for(int p=start;p<=end;p++)if(otherParts.contains(p))intersects=true;if(intersects){overlapCount++;if(j<i)overlapIndex++;}}
                int sub=cell/overlapCount;TextView block=a.text(course.getString("name")+"\n"+course.optString("location"),10,a.ink);block.setPadding(a.d(3),a.d(4),a.d(3),a.d(2));block.setEllipsize(android.text.TextUtils.TruncateAt.END);block.setTypeface(null,Typeface.BOLD);block.setGravity(Gravity.TOP);block.setBackground(a.bg(a.dark?new int[]{0xFF213E52,0xFF263C35,0xFF43344E,0xFF4A3C28}[i%4]:new int[]{0xFFDCEBFA,0xFFDDEEE2,0xFFEBDFF5,0xFFFAECD5}[i%4],6));
                final JSONObject selected=course;block.setOnClickListener(v->courseMenu(selected));block.setContentDescription(course.getString("name")+"，"+course.optString("location")+"，点击编辑");place(grid,block,label+(day-1)*cell+overlapIndex*sub+a.d(2),top+(start-1)*row+a.d(2),sub-a.d(4),(end-start+1)*row-a.d(4));
            }
        }
        horizontal.addView(grid,new HorizontalScrollView.LayoutParams(width,-1));a.root.addView(horizontal,new LinearLayout.LayoutParams(-1,0,1));horizontal.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int available=b-t;if(available<=top)return;float sx=(float)(r-l-label)/(5*cell),sy=(float)(available-top)/(11*row);grid.getLayoutParams().width=label+Math.round(7*cell*sx);grid.requestLayout();for(int n=0;n<grid.getChildCount();n++){View child=grid.getChildAt(n);int[] original=(int[])child.getTag();FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)child.getLayoutParams();p.leftMargin=original[0]<label?original[0]:label+Math.round((original[0]-label)*sx);p.topMargin=original[1]<top?original[1]:top+Math.round((original[1]-top)*sy);p.width=original[0]<label?original[2]:Math.round(original[2]*sx);p.height=original[1]<top?original[3]:Math.max(1,Math.round(original[3]*sy));child.setLayoutParams(p);if(child instanceof TextView&&original[0]>=label&&original[1]>=top)((TextView)child).setMaxLines(Math.max(1,(p.height-child.getPaddingTop()-child.getPaddingBottom())/((TextView)child).getLineHeight()));}});
        if(visible==0){TextView tip=a.text("本周暂无课程 · 添加课程或导入 JSON",13,a.muted);tip.setPadding(0,a.d(8),0,a.d(8));a.root.addView(tip);}
        LinearLayout actions=new LinearLayout(a);actions.addView(a.button("＋ 课程",()->editCourse(null)),new LinearLayout.LayoutParams(0,a.d(48),1));actions.addView(a.button("学期与节次",this::termEditor),new LinearLayout.LayoutParams(0,a.d(48),1));actions.addView(a.button("导入 / 导出",this::importMenu),new LinearLayout.LayoutParams(0,a.d(48),1));a.root.addView(actions);a.navigation("timetable");
    }catch(Exception e){a.error(e);}}
    void place(FrameLayout grid,View view,int left,int top,int width,int height){view.setTag(new int[]{left,top,width,height});FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(width,height);p.leftMargin=left;p.topMargin=top;grid.addView(view,p);}
    void pickWeek(int first,int last){String[] weeks=new String[last-first+1];for(int i=0;i<weeks.length;i++)weeks[i]="第 "+(i+first)+" 周";Ui.select(a,"选择周次",weeks,selectedWeek-first,n->{selectedWeek=first+n;show();});}
    void courseMenu(JSONObject course){new AlertDialog.Builder(a).setTitle(course.optString("name")).setMessage("周次："+TimetableStore.numbersText(course.optJSONArray("weeks"))+"\n节次："+TimetableStore.numbersText(course.optJSONArray("periods"))+"\n地点："+course.optString("location")+"\n教师："+course.optString("teacher")).setPositiveButton("编辑",(d,w)->editCourse(course)).setNeutralButton("删除",(d,w)->{
        try{JSONArray all=data.getJSONArray("courses"),keep=new JSONArray();for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).getString("id").equals(course.getString("id")))keep.put(all.get(i));data.put("courses",keep);TimetableStore.save(a,data);show();Toast.makeText(a,"已删除，可在导入菜单恢复上次编辑",Toast.LENGTH_LONG).show();}catch(Exception e){a.error(e);}
    }).setNegativeButton("关闭",null).show();}
    EditText input(LinearLayout form,String label,String value){form.addView(a.text(label,13,a.muted));EditText e=new EditText(a);e.setTextSize(16);e.setTextColor(a.ink);e.setText(value);e.setSingleLine(true);form.addView(e,new LinearLayout.LayoutParams(-1,a.d(50)));return e;}
    void editCourse(JSONObject old){try{
        LinearLayout form=a.column();form.setPadding(a.d(20),a.d(10),a.d(20),a.d(12));EditText name=input(form,"课程名称",old==null?"":old.optString("name"));EditText location=input(form,"地点",old==null?"":old.optString("location"));EditText teacher=input(form,"教师（可选）",old==null?"":old.optString("teacher"));
        Ui.Choice day=AttentionSettings.choice(a,form,"星期",new String[]{"周一","周二","周三","周四","周五","周六","周日"},old==null?0:old.optInt("day",1)-1);
        JSONObject term=data.getJSONObject("term");EditText weeks=input(form,"周次 · 如 1-16、1-16单、2,4,6",old==null?term.getInt("start_week")+"-"+term.getInt("end_week"):TimetableStore.numbersText(old.getJSONArray("weeks")));EditText parts=input(form,"节次 · 如 1-2、5,6",old==null?"1-2":TimetableStore.numbersText(old.getJSONArray("periods")));
        ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(old==null?"添加课程":"编辑课程").setView(scroll).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(x->{try{
            JSONObject course=new JSONObject().put("id",old==null?UUID.randomUUID().toString():old.getString("id")).put("name",name.getText().toString().trim()).put("location",location.getText().toString().trim()).put("teacher",teacher.getText().toString().trim()).put("day",day.getSelectedItemPosition()+1).put("weeks",TimetableStore.array(TimetableData.numbers(weeks.getText().toString(),term.getInt("start_week"),term.getInt("end_week")))).put("periods",TimetableStore.array(TimetableData.numbers(parts.getText().toString(),1,11)));
            JSONArray current=data.getJSONArray("courses"),next=new JSONArray();boolean replaced=false;for(int i=0;i<current.length();i++){JSONObject row=current.getJSONObject(i);if(row.getString("id").equals(course.getString("id"))){next.put(course);replaced=true;}else next.put(row);}if(!replaced)next.put(course);JSONObject edited=new JSONObject(data.toString()).put("courses",next);TimetableStore.save(a,edited);dialog.dismiss();show();
        }catch(Exception ex){a.error(ex);}}));dialog.show();
    }catch(Exception e){a.error(e);}}
    void termEditor(){try{
        JSONObject term=data.getJSONObject("term");LinearLayout form=a.column();form.setPadding(a.d(20),a.d(10),a.d(20),a.d(12));EditText name=input(form,"学期名称",term.optString("name"));EditText monday=input(form,"第一周周一 · yyyy-MM-dd",term.getString("week1_monday"));EditText first=input(form,"起始周",term.getInt("start_week")+"");EditText last=input(form,"结束周",term.getInt("end_week")+"");first.setInputType(2);last.setInputType(2);
        EditText[] begins=new EditText[11],ends=new EditText[11];JSONArray times=data.getJSONArray("periods");for(int i=0;i<11;i++){form.addView(a.text("第 "+(i+1)+" 节",15,a.ink));LinearLayout row=new LinearLayout(a);begins[i]=new EditText(a);ends[i]=new EditText(a);begins[i].setText(times.getJSONObject(i).getString("start"));ends[i].setText(times.getJSONObject(i).getString("end"));begins[i].setSingleLine();ends[i].setSingleLine();row.addView(begins[i],new LinearLayout.LayoutParams(0,a.d(50),1));row.addView(ends[i],new LinearLayout.LayoutParams(0,a.d(50),1));form.addView(row);}
        ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("学期与节次").setView(scroll).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(x->{try{
            JSONObject edited=new JSONObject(data.toString());edited.put("term",new JSONObject().put("name",name.getText().toString()).put("week1_monday",monday.getText().toString().trim()).put("start_week",Integer.parseInt(first.getText().toString())).put("end_week",Integer.parseInt(last.getText().toString())));
            JSONArray periods=new JSONArray();for(int i=0;i<11;i++)periods.put(new JSONObject().put("number",i+1).put("start",begins[i].getText().toString().trim()).put("end",ends[i].getText().toString().trim()));edited.put("periods",periods);TimetableStore.save(a,edited);dialog.dismiss();selectedWeek=-1;show();
        }catch(Exception ex){a.error(ex);}}));dialog.show();
    }catch(Exception e){a.error(e);}}
    void importMenu(){Ui.select(a,"课表 JSON",new String[]{"选择 JSON 文件导入","粘贴 JSON 导入","导出当前课表","复制空白模板","恢复上次编辑"},-1,n->{
        if(n==0)a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),41);
        else if(n==1){EditText input=new EditText(a);input.setMinLines(6);input.setTextSize(13);input.setHint("粘贴课表 JSON");AlertDialog dialog=new AlertDialog.Builder(a).setTitle("导入课表").setView(input).setNegativeButton("取消",null).setPositiveButton("校验并导入",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(x->{if(importJson(input.getText().toString()))dialog.dismiss();}));dialog.show();}
        else if(n==2)a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"DCP-Timetable.json"),42);
        else if(n==3){((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("课表模板",TimetableStore.empty().toString()));Toast.makeText(a,"空白模板已复制",Toast.LENGTH_SHORT).show();}
        else try{TimetableStore.undo(a);show();}catch(Exception e){a.error(e);}
    });}
    boolean importJson(String json){try{if(json.length()>1024*1024)throw new IllegalArgumentException("JSON 文件不能超过 1 MB");JSONObject parsed=TimetableStore.validate(new JSONObject(json));TimetableStore.save(a,parsed);selectedWeek=-1;show();Toast.makeText(a,"课表已导入，可恢复上次编辑",Toast.LENGTH_LONG).show();return true;}catch(Exception e){a.error(e);return false;}}
}
